afterEach(function (): void {
    Facade::clearResolvedInstances();
    Container::setInstance(null);
});

it('registers through its service provider and merges its config', function () {
    TestApp::boot();
    expect(config('connectors.google-calendar.mode'))->toBe('auto');
    expect(config('connectors.google-calendar.credentials'))->toBeArray();
});

it('fakes channel_stop and records it for assertSent', function () {
    TestApp::boot();
    GoogleCalendar::fake();
    $config = [
        'channelId' => 'example-channelId',
        'resourceId' => 'example-resourceId',
    ];
    $result = GoogleCalendar::call('channel_stop', $config);

    expect($result->mode->value)->toBe('fake');
    GoogleCalendar::assertSent('channel_stop', fn (array $sent): bool => $sent == $config);
    GoogleCalendar::assertNotSent('no_such_operation');
    GoogleCalendar::assertSentCount(1);
});

it('refuses a forged events_changed delivery before the app sees it', function () {
    $app = TestApp::boot();
    $app['router']->googleCalendarEventsChanged('/hooks/google-calendar');
    $response = TestApp::dispatch($app, Request::create('/hooks/google-calendar', 'POST', server: ['CONTENT_TYPE' => 'application/json'], content: '{"forged":true}'));

    expect($response->getStatusCode())->toBe(401);
});
